import { EventEmitter } from 'node:events';

export const ErrorCodes = Object.freeze({
  ParseError: -32700,
  InvalidRequest: -32600,
  MethodNotFound: -32601,
  InvalidParams: -32602,
  InternalError: -32603,
  ServerNotInitialized: -32002,
  UnknownErrorCode: -32001,
  RequestCancelled: -32800,
  ContentModified: -32801,
});

export class ResponseError extends Error {
  constructor(code, message, data) {
    super(message);
    this.name = 'ResponseError';
    this.code = code;
    this.data = data;
  }

  toJson() {
    const result = { code: this.code, message: this.message };
    if (this.data !== undefined) {
      result.data = this.data;
    }
    return result;
  }
}

export class CancellationTokenSource {
  constructor() {
    this._emitter = new EventEmitter();
    this._isCancelled = false;
    this.token = {
      isCancellationRequested: false,
      onCancellationRequested: (listener) => {
        if (this._isCancelled) {
          listener();
          return { dispose: () => {} };
        }
        this._emitter.on('cancel', listener);
        return { dispose: () => this._emitter.off('cancel', listener) };
      },
    };
  }

  cancel() {
    if (!this._isCancelled) {
      this._isCancelled = true;
      this.token.isCancellationRequested = true;
      this._emitter.emit('cancel');
    }
  }

  dispose() {
    this._emitter.removeAllListeners();
  }
}

const MAX_HEADER_BYTES = 8192;
const MAX_CONTENT_LENGTH = 16 * 1024 * 1024;

export class StreamMessageReader {
  constructor(readable) {
    this.readable = readable;
    this._buffer = Buffer.alloc(0);
    this._emitter = new EventEmitter();
    this._listening = false;
    this._closed = false;
    this._disposed = false;
    this._onData = null;
    this._onError = null;
    this._onClose = null;
  }

  _emitClose() {
    if (this._closed) return;
    this._closed = true;
    this._emitter.emit('close');
  }

  listen(callback) {
    this._emitter.on('message', callback);
    if (this._listening || this._disposed) {
      return { dispose: () => this._emitter.off('message', callback) };
    }
    this._listening = true;

    this._onData = (chunk) => {
      if (this._disposed) return;
      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, 'utf8');
      this._buffer = this._buffer.length === 0 ? buf : Buffer.concat([this._buffer, buf]);
      this._drainMessages();
    };
    this._onError = (err) => {
      if (!this._disposed && this._emitter.listenerCount('error') > 0) {
        this._emitter.emit('error', err);
      }
    };
    this._onClose = () => {
      if (!this._disposed) {
        this._emitClose();
      }
    };

    this.readable.on('data', this._onData);
    this.readable.on('error', this._onError);
    this.readable.on('close', this._onClose);
    this.readable.on('end', this._onClose);

    return { dispose: () => this._emitter.off('message', callback) };
  }

  _drainMessages() {
    while (true) {
      const crlfIdx = this._buffer.indexOf('\r\n\r\n');
      const lfIdx = this._buffer.indexOf('\n\n');
      let idx = -1;
      let sepLen = 4;
      if (crlfIdx !== -1 && (lfIdx === -1 || crlfIdx <= lfIdx)) {
        idx = crlfIdx;
        sepLen = 4;
      } else if (lfIdx !== -1) {
        idx = lfIdx;
        sepLen = 2;
      }
      if (idx === -1) {
        if (this._buffer.length > MAX_HEADER_BYTES) {
          const err = new Error(`JSON-RPC header exceeded ${MAX_HEADER_BYTES} bytes`);
          this._buffer = Buffer.alloc(0);
          if (this._emitter.listenerCount('error') > 0) {
            this._emitter.emit('error', err);
          }
        }
        return;
      }
      if (idx > MAX_HEADER_BYTES) {
        const err = new Error(`JSON-RPC header exceeded ${MAX_HEADER_BYTES} bytes`);
        this._buffer = Buffer.alloc(0);
        if (this._emitter.listenerCount('error') > 0) {
          this._emitter.emit('error', err);
        }
        return;
      }

      const headerStr = this._buffer.subarray(0, idx).toString('ascii');
      const match = /Content-Length:\s*(\d+)/i.exec(headerStr);
      if (!match) {
        this._buffer = idx + sepLen >= this._buffer.length ? Buffer.alloc(0) : this._buffer.subarray(idx + sepLen);
        continue;
      }

      const contentLength = Number.parseInt(match[1], 10);
      if (!Number.isFinite(contentLength) || contentLength < 0 || contentLength > MAX_CONTENT_LENGTH) {
        const err = new Error(`Invalid Content-Length: ${match[1]}`);
        this._buffer = Buffer.alloc(0);
        if (this._emitter.listenerCount('error') > 0) {
          this._emitter.emit('error', err);
        }
        return;
      }

      const bodyStart = idx + sepLen;
      if (this._buffer.length < bodyStart + contentLength) {
        return;
      }

      const bodyBuf = this._buffer.subarray(bodyStart, bodyStart + contentLength);
      const remaining = this._buffer.length - (bodyStart + contentLength);
      this._buffer = remaining === 0 ? Buffer.alloc(0) : Buffer.from(this._buffer.subarray(bodyStart + contentLength));
      try {
        const msg = JSON.parse(bodyBuf.toString('utf8'));
        this._emitter.emit('message', msg);
      } catch (err) {
        if (this._emitter.listenerCount('error') > 0) {
          this._emitter.emit('error', err);
        }
      }
    }
  }

  onError(cb) {
    this._emitter.on('error', cb);
    return { dispose: () => this._emitter.off('error', cb) };
  }

  onClose(cb) {
    this._emitter.on('close', cb);
    return { dispose: () => this._emitter.off('close', cb) };
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    if (this.readable) {
      if (this._onData) this.readable.off('data', this._onData);
      if (this._onError) this.readable.off('error', this._onError);
      if (this._onClose) {
        this.readable.off('close', this._onClose);
        this.readable.off('end', this._onClose);
      }
    }
    this._buffer = Buffer.alloc(0);
    this._emitter.removeAllListeners();
  }
}

export class StreamMessageWriter {
  constructor(writable) {
    this.writable = writable;
    this._emitter = new EventEmitter();
    this._closed = false;
    this._disposed = false;

    this._onError = (err) => {
      if (!this._disposed && this._emitter.listenerCount('error') > 0) {
        this._emitter.emit('error', err);
      }
    };
    this._onClose = () => {
      if (!this._closed && !this._disposed) {
        this._closed = true;
        this._emitter.emit('close');
      }
    };

    if (this.writable && typeof this.writable.on === 'function') {
      this.writable.on('error', this._onError);
      this.writable.on('close', this._onClose);
      this.writable.on('finish', this._onClose);
    }
  }

  write(msg) {
    if (
      this._disposed ||
      this._closed ||
      !this.writable ||
      this.writable.destroyed ||
      this.writable.writableEnded
    ) {
      return Promise.reject(new Error('StreamMessageWriter stream is closed or destroyed'));
    }
    const json = JSON.stringify(msg);
    const byteLen = Buffer.byteLength(json, 'utf8');
    const payload = `Content-Length: ${byteLen}\r\n\r\n${json}`;
    return new Promise((resolve, reject) => {
      try {
        this.writable.write(payload, 'utf8', (err) => {
          if (err) {
            if (this._emitter.listenerCount('error') > 0) {
              this._emitter.emit('error', err);
            }
            reject(err);
          } else {
            resolve();
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  onError(cb) {
    this._emitter.on('error', cb);
    return { dispose: () => this._emitter.off('error', cb) };
  }

  onClose(cb) {
    this._emitter.on('close', cb);
    return { dispose: () => this._emitter.off('close', cb) };
  }

  end() {
    if (this.writable && typeof this.writable.end === 'function') {
      this.writable.end();
    }
  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    if (this.writable && typeof this.writable.off === 'function') {
      this.writable.off('error', this._onError);
      this.writable.off('close', this._onClose);
      this.writable.off('finish', this._onClose);
    }
    this._emitter.removeAllListeners();
  }
}

export function createMessageConnection(readerOrInput, writerOrOutput) {
  const reader =
    typeof readerOrInput?.listen === 'function'
      ? readerOrInput
      : new StreamMessageReader(readerOrInput);
  const writer =
    writerOrOutput instanceof StreamMessageWriter ||
    (typeof writerOrOutput?.write === 'function' &&
      typeof writerOrOutput?.onError === 'function' &&
      typeof writerOrOutput?.dispose === 'function')
      ? writerOrOutput
      : new StreamMessageWriter(writerOrOutput);

  const emitter = new EventEmitter();
  const requestHandlers = new Map();
  const notificationHandlers = new Map();
  const pendingRequests = new Map();
  const activeRequestTokens = new Map();
  let nextId = 1;
  let disposed = false;
  let closed = false;
  let listening = false;

  const emitErrorSafe = (err) => {
    if (emitter.listenerCount('error') > 0) {
      emitter.emit('error', err);
    }
  };

  const rejectAllPending = (reason) => {
    for (const [, pending] of pendingRequests) {
      pending.reject(reason);
    }
    pendingRequests.clear();
  };

  const handleClose = () => {
    if (closed) return;
    closed = true;
    rejectAllPending(new Error('Connection closed'));
    emitter.emit('close');
  };

  const safeWrite = async (payload) => {
    try {
      await writer.write(payload);
    } catch (err) {
      emitErrorSafe(err);
    }
  };

  const handleMessage = async (msg) => {
    if (!msg || typeof msg !== 'object') {
      return;
    }

    if (msg.method === '$/cancelRequest' && msg.params && msg.params.id !== undefined) {
      const cts = activeRequestTokens.get(msg.params.id);
      cts?.cancel();
      return;
    }

    if (msg.method !== undefined && msg.id !== undefined) {
      const handler = requestHandlers.get(msg.method);
      if (!handler) {
        await safeWrite({
          jsonrpc: '2.0',
          id: msg.id,
          error: { code: ErrorCodes.MethodNotFound, message: `Method not found: ${msg.method}` },
        });
        return;
      }
      const cts = new CancellationTokenSource();
      activeRequestTokens.set(msg.id, cts);
      try {
        const result = await handler(msg.params, cts.token);
        await safeWrite({ jsonrpc: '2.0', id: msg.id, result: result ?? null });
      } catch (err) {
        const errorObj =
          err instanceof ResponseError
            ? err.toJson()
            : { code: ErrorCodes.InternalError, message: err instanceof Error ? err.message : String(err) };
        await safeWrite({ jsonrpc: '2.0', id: msg.id, error: errorObj });
      } finally {
        activeRequestTokens.delete(msg.id);
        cts.dispose();
      }
      return;
    }

    if (msg.method !== undefined && msg.id === undefined) {
      const handlers = notificationHandlers.get(msg.method);
      if (handlers) {
        for (const h of handlers) {
          try {
            await h(msg.params);
          } catch (err) {
            emitErrorSafe(err);
          }
        }
      }
      return;
    }

    if (msg.id !== undefined) {
      const pending = pendingRequests.get(msg.id);
      if (pending) {
        pendingRequests.delete(msg.id);
        if (msg.error) {
          pending.reject(
            new ResponseError(
              msg.error.code ?? ErrorCodes.InternalError,
              msg.error.message ?? 'Unknown JSON-RPC error',
              msg.error.data,
            ),
          );
        } else {
          pending.resolve(msg.result);
        }
      }
    }
  };

  const connection = {
    listen() {
      if (listening || disposed || closed) {
        return;
      }
      listening = true;
      reader.listen(handleMessage);
      reader.onError((err) => {
        rejectAllPending(err instanceof Error ? err : new Error(String(err)));
        emitErrorSafe(err);
      });
      reader.onClose(handleClose);
      writer.onError((err) => {
        rejectAllPending(err instanceof Error ? err : new Error(String(err)));
        emitErrorSafe(err);
      });
      if (typeof writer.onClose === 'function') {
        writer.onClose(handleClose);
      }
    },

    onRequest(methodOrType, handler) {
      const method = typeof methodOrType === 'string' ? methodOrType : methodOrType.method;
      requestHandlers.set(method, handler);
      return { dispose: () => requestHandlers.delete(method) };
    },

    onNotification(methodOrType, handler) {
      const method = typeof methodOrType === 'string' ? methodOrType : methodOrType.method;
      if (!notificationHandlers.has(method)) {
        notificationHandlers.set(method, new Set());
      }
      notificationHandlers.get(method).add(handler);
      return { dispose: () => notificationHandlers.get(method)?.delete(handler) };
    },

    sendRequest(methodOrType, params) {
      const method = typeof methodOrType === 'string' ? methodOrType : methodOrType.method;
      if (disposed || closed) {
        return Promise.reject(new Error(disposed ? 'Connection is disposed' : 'Connection is closed'));
      }
      const id = nextId++;
      return new Promise((resolve, reject) => {
        pendingRequests.set(id, { resolve, reject });
        writer.write({ jsonrpc: '2.0', id, method, params }).catch((err) => {
          pendingRequests.delete(id);
          reject(err);
        });
      });
    },

    sendNotification(methodOrType, params) {
      const method = typeof methodOrType === 'string' ? methodOrType : methodOrType.method;
      if (disposed || closed) {
        return Promise.resolve();
      }
      return writer.write({ jsonrpc: '2.0', method, params }).catch(() => {});
    },

    onClose(cb) {
      emitter.on('close', cb);
      return { dispose: () => emitter.off('close', cb) };
    },

    onError(cb) {
      emitter.on('error', cb);
      return { dispose: () => emitter.off('error', cb) };
    },

    onDispose(cb) {
      emitter.on('dispose', cb);
      return { dispose: () => emitter.off('dispose', cb) };
    },

    end() {
      writer.end();
    },

    dispose() {
      if (disposed) {
        return;
      }
      disposed = true;
      closed = true;
      for (const cts of activeRequestTokens.values()) {
        cts.cancel();
        cts.dispose();
      }
      activeRequestTokens.clear();
      rejectAllPending(new Error('Connection disposed'));
      reader.dispose();
      writer.dispose();
      emitter.emit('dispose');
      emitter.removeAllListeners();
    },
  };

  return connection;
}

export default {
  ErrorCodes,
  ResponseError,
  CancellationTokenSource,
  StreamMessageReader,
  StreamMessageWriter,
  createMessageConnection,
};
